#!/usr/bin/env bash
# Creates the secrets owned by the Administration Service in AWS Secrets Manager (owner: Joseph). Safe to run again.
#   roadhub/jwt-private, roadhub/jwt-public, roadhub/internal, roadhub/turnstile
# Run this FIRST on a new Floci: the other two services need roadhub/jwt-public and roadhub/internal.
# Values are generated by Node or read from infra/.env; they are never printed.
source "$(dirname "$0")/../lib.sh"
step "Secrets Manager: admin-service"
[ -f "$ROOT_DIR/infra/.env" ] && set -a && . <(sed 's/\r$//' "$ROOT_DIR/infra/.env") && set +a
(cd "$ROOT_DIR" && node infra/scripts/create-secrets.js)
